2	
3	const MAX_CONTENT_LENGTH = 10000;
4	
5	interface ValidationSuccess {
6	  valid: true;
7	  data: IncomingMessage;
8	}
9	
10	interface ValidationFailure {
11	  valid: false;
12	  error: string;
13	}
14	
15	export type ValidationResult = ValidationSuccess | ValidationFailure;
16	
17	export function validateMessage(payload: unknown): ValidationResult {
18	  if (typeof payload !== 'object' || payload === null) {
19	    return {valid: false, error: 'Message must be an object'};
20	  }
21	
22	  const message = payload as Record<string, unknown>;
23	
24	  if (typeof message.type !== 'string') {
25	    return {valid: false, error: 'Message must have a type field'};
26	  }
27	
28	  switch (message.type) {
29	    case 'user_message':
30	      return validateUserMessage(message);
31	    case 'ping':
32	      return validatePingMessage(message);
33	    case 'list_sessions':
34	      return validateListSessionsMessage(message);
35	    default:
36	      return {valid: false, error: `Unknown message type: ${message.type}`};
37	  }
38	}
39	
40	function validateUserMessage(message: Record<string, unknown>): ValidationResult {
41	  if (typeof message.content !== 'string') {
42	    return {valid: false, error: 'user_message must have content string'};
43	  }
44	
45	  const trimmed = message.content.trim();
46	
47	  if (trimmed.length === 0) {
48	    return {valid: false, error: 'Message content cannot be empty'};
49	  }
50	
51	  if (message.content.length > MAX_CONTENT_LENGTH) {
52	    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
53	  }
54	
55	  return {
56	    valid: true,
57	    data: {
58	      type: 'user_message',
59	      content: message.content,
60	    },
61	  };
62	}
63	
64	function validatePingMessage(message: Record<string, unknown>): ValidationResult {
65	  if (typeof message.timestamp !== 'number') {
66	    return {valid: false, error: 'ping must have timestamp number'};
67	  }
68	
69	  return {
70	    valid: true,
71	    data: {
72	      type: 'ping',
73	      timestamp: message.timestamp,
74	    },
75	  };
76	}
77	
78	function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
79	  if (message.limit !== undefined) {
80	    if (typeof message.limit !== 'number' || !Number.isInteger(message.limit)) {
81	      return {valid: false, error: 'list_sessions limit must be an integer'};
82	    }
83	    if (message.limit < 0) {
84	      return {valid: false, error: 'list_sessions limit must be non-negative'};
85	    }
86	  }
87	
88	  if (message.before !== undefined) {
89	    if (typeof message.before !== 'object' || message.before === null || Array.isArray(message.before)) {
90	      return {valid: false, error: 'list_sessions before must be an object'};
91	    }
92	    const before = message.before as Record<string, unknown>;
93	    if (typeof before.sessionId !== 'string' || before.sessionId.length < 1 || before.sessionId.length > 128) {
94	      return {valid: false, error: 'list_sessions before.sessionId must be a string of 1-128 chars'};
95	    }
96	    const updatedAt = before.updatedAt;
97	    const isValidDate =
98	      (typeof updatedAt === 'string' && !isNaN(Date.parse(updatedAt))) ||
99	      (typeof updatedAt === 'number' && isFinite(updatedAt));
100	    if (!isValidDate) {
101	      return {valid: false, error: 'list_sessions before.updatedAt must be a valid date string or epoch number'};
102	    }
103	  }
104	
105	  const data: ListSessionsMessage = {type: 'list_sessions'};
106	  if (message.limit !== undefined) data.limit = message.limit as number;
107	  if (message.before !== undefined) {
108	    const before = message.before as Record<string, unknown>;
109	    data.before = {
110	      sessionId: before.sessionId as string,
111	      updatedAt: before.updatedAt as string | number,
112	    };
113	  }
114	
115	  return {valid: true, data};
116	}
