1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {OutgoingMessage} from '../../types/messages.js';
6	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
7	import {validateMessage} from './validation.js';
8	import type {ValidationResult} from './validation.js';
9	import {PerSessionLock} from '../../shared/perSessionLock.js';
10	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
11	import {AIError} from '../../types/ai.js';
12	import type {MessageChunk} from '../../types/ai.js';
13	import {
14	  createUserEntry,
15	  createAssistantEntry,
16	  createThinkingEntry,
17	  createToolEntry,
18	} from '../../orchestration/entryFactories.js';
19	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
20	import {sendJson, sendUpsert, sendDelta, sendCommit, sendSkip, sendError, sendStreamEnd} from './sender.js';
21	import {log} from '../../shared/logger.js';
22	import type {SessionStore} from '../../types/sessionStore.js';
23	import type {SessionSummaryFrame} from '../../types/messages.js';
24	
25	interface StreamState {
26	  thinkingIndex: number | null;
27	  assistantIndex: number | null;
28	  suppressOutput: boolean;
29	  sentAssistantIndices: number[];
30	}
31	
32	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
33	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
34	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
35	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
36	  const lock = new PerSessionLock();
37	  return function handleMessage(
38	    ws: WebSocket,
39	    session: ChatSession,
40	    rawMessage: unknown,
41	    signal?: AbortSignal
42	  ): Promise<void> {
43	    const validation = validateMessage(rawMessage);
44	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
45	    if (isUserMessageFrame(rawMessage)) {
46	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
47	    }
48	    if (isListSessionsFrame(rawMessage)) {
49	      return wsErrorHandler(ws, () => answerListSessions(ws, session, sessionStore, validation));
50	    }
51	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
52	    return wsErrorHandler(ws, async () => answerFrame(ws, validation));
53	  };
54	}
55	
56	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
57	async function answerInTurn(
58	  ws: WebSocket,
59	  session: ChatSession,
60	  orchestrator: ChatOrchestrator,
61	  validation: ValidationResult,
62	  signal: AbortSignal | undefined
63	): Promise<void> {
64	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
65	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
66	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
67	    return;
68	  }
69	  const startedAt = Date.now();
70	  try {
71	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
72	  } finally {
73	    endTurn(ws, session, signal, startedAt);
74	  }
75	}
76	
77	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
78	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
79	  if (signal?.aborted) {
80	    log.info('message', 'turn abandoned: its socket closed', {
81	      sessionId: session.sessionId,
82	      elapsedMs: Date.now() - startedAt,
83	    });
84	    return;
85	  }
86	  sendStreamEnd(ws);
87	}
88	
89	async function answerUserMessage(
90	  ws: WebSocket,
91	  session: ChatSession,
92	  orchestrator: ChatOrchestrator,
93	  validation: ValidationResult,
94	  signal: AbortSignal | undefined
95	): Promise<void> {
96	  const message = validation.valid ? validation.data : undefined;
97	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
98	  answerFrame(ws, validation);
99	}
100	
101	function answerFrame(ws: WebSocket, validation: ValidationResult): void {
102	  if (!validation.valid) {
103	    log.warn('message', 'validation failed', {error: validation.error});
104	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
105	    return;
106	  }
107	
108	  const message = validation.data;
109	  if (message.type === 'ping') handlePing(ws, message.timestamp);
110	}
111	
112	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
113	function isUserMessageFrame(rawMessage: unknown): boolean {
114	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
115	}
116	
117	function isListSessionsFrame(rawMessage: unknown): boolean {
118	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'list_sessions';
119	}
120	
121	async function answerListSessions(
122	  ws: WebSocket,
123	  session: ChatSession,
124	  store: SessionStore | undefined,
125	  validation: ValidationResult
126	): Promise<void> {
127	  if (!validation.valid) {
128	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
129	    return;
130	  }
131	  const msg = validation.data;
132	  if (msg.type !== 'list_sessions') return;
133	
134	  if (!store?.listFor) {
135	    sendJson(ws, {type: 'session_list', sessions: []});
136	    return;
137	  }
138	
139	  try {
140	    const summaries = await store.listFor(session.userId, {limit: msg.limit, before: msg.before});
141	    sendJson(ws, {type: 'session_list', sessions: summaries.map(toSummaryFrame)});
142	  } catch (err) {
143	    const errMsg = err instanceof Error ? err.message : 'Unknown error';
144	    log.error('ws', 'listFor failed', {userId: session.userId, error: errMsg});
145	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
146	  }
147	}
148	
149	function toSummaryFrame(s: {
150	  sessionId: string;
151	  createdAt: Date | string;
152	  updatedAt: Date | string;
153	  entryCount: number;
154	}): SessionSummaryFrame {
155	  return {
156	    sessionId: s.sessionId,
157	    createdAt: s.createdAt instanceof Date ? s.createdAt.toISOString() : String(s.createdAt),
158	    updatedAt: s.updatedAt instanceof Date ? s.updatedAt.toISOString() : String(s.updatedAt),
159	    entryCount: s.entryCount,
160	  };
161	}
162	
163	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
164	  try {
165	    await action();
166	  } catch (error) {
167	    const message = error instanceof Error ? error.message : 'Unknown error';
168	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
169	    log.error('message', 'handling error', {error: message, code});
170	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
171	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
172	      return;
173	    }
174	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
175	  }
176	}
177	
178	async function handleUserMessage(
179	  ws: WebSocket,
180	  session: ChatSession,
181	  orchestrator: ChatOrchestrator,
182	  content: string,
183	  signal: AbortSignal | undefined
184	): Promise<void> {
185	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
186	
187	  const userEntry = createUserEntry(content);
188	  const userIndex = appendEntry(session, userEntry);
189	  sendUpsert(ws, userIndex, userEntry);
190	
191	  const parser = new ThinkingTagParser();
192	  const state: StreamState = {
193	    thinkingIndex: null,
194	    assistantIndex: null,
195	    suppressOutput: false,
196	    sentAssistantIndices: [],
197	  };
198	
199	  let textChunkCount = 0;
200	
201	  try {
202	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
203	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
204	      if (signal?.aborted) break;
205	      textChunkCount = logChunk(chunk, textChunkCount);
206	      processChunk(ws, session, state, parser, chunk);
207	    }
208	  } finally {
209	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
210	    flushHeldText(ws, session, state, parser);
211	    closeCutOff(ws, session, state, 'thinkingIndex');
212	    closeCutOff(ws, session, state, 'assistantIndex');
213	  }
214	
215	  if (textChunkCount > 0) {
216	    log.debug('stream', `received ${textChunkCount} text chunks`);
217	  }
218	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
219	}
220	
221	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
222	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
223	  if (chunk.type === 'text') return textChunkCount + 1;
224	
225	  if (textChunkCount > 0) {
226	    log.debug('stream', `received ${textChunkCount} text chunks`);
227	  }
228	
229	  if (chunk.type === 'tool_result') {
230	    log.debug('stream', 'tool_result chunk', {
231	      messageCount: chunk.clientMessages.length,
232	      types: chunk.clientMessages.map(m => m.type),
233	    });
234	    return 0;
235	  }
236	
237	  log.debug('stream', 'chunk', {type: chunk.type});
238	  return 0;
239	}
240	
241	function processChunk(
242	  ws: WebSocket,
243	  session: ChatSession,
244	  state: StreamState,
245	  parser: ThinkingTagParser,
246	  chunk: MessageChunk
247	): void {
248	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
249	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
250	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
251	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
252	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
253	}
254	
255	function processTextChunk(
256	  ws: WebSocket,
257	  session: ChatSession,
258	  state: StreamState,
259	  parser: ThinkingTagParser,
260	  text: string
261	): void {
262	  const segments = parser.push(text);
263	  for (const segment of segments) {
264	    handleTextSegment(ws, session, state, segment);
265	  }
266	}
